edits.newText:
import { isBillableInvoice } from "./isBillableInvoice";

export function invoiceActions(status: "draft" | "sent" | "paid") {
  const billable = isBillableInvoice(status);
  return billable ? ["remind", "refund"] : ["edit"];
}

export function isBillableInvoice(status: "draft" | "sent" | "paid") {
  return status === "sent" || status === "paid";
}
